using System;using System.IO;using System.Linq;using System.Collections.Generic;using Mono.Cecil;
class Verify {static IEnumerable<TypeDefinition> All(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in All(t.NestedTypes))yield return n;}}static Dictionary<string,int> Calls(string p,string prefix){using(var a=AssemblyDefinition.ReadAssembly(p)){var d=new Dictionary<string,int>();foreach(var m in All(a.MainModule.Types).SelectMany(t=>t.Methods).Where(m=>m.HasBody))foreach(var i in m.Body.Instructions){var r=i.Operand as MethodReference;if(r!=null && r.DeclaringType.FullName.StartsWith(prefix)){int n;d.TryGetValue(r.FullName,out n);d[r.FullName]=n+1;}}return d;}}static void Main(string[] a){foreach(var name in new[]{"World.dll","Commons.dll"}){var before=Calls(Path.Combine(a[0],name),"OneWayDps.");var after=Calls(Path.Combine(a[1],name),"OneWayDps.");foreach(var c in before)if(!after.ContainsKey(c.Key)||after[c.Key]!=c.Value)throw new Exception("DPS hook changed: "+c.Key);Console.WriteLine(name+": preserved "+before.Values.Sum()+" DPS hook calls");}var hooks=Calls(Path.Combine(a[1],"World.dll"),"OneWaySpeaker.Hooks");foreach(var method in new[]{"Begin","End","Attack","PanelAttack","Attach","LoadSprite","EnterRest","LeaveRest","FitPreview","AttachUi"})if(!hooks.Keys.Any(k=>k.Contains("::"+method+"(")))throw new Exception("Missing "+method);Console.WriteLine("Speaker lifecycle, attack, UI and world view hooks verified.");using(var commons=AssemblyDefinition.ReadAssembly(Path.Combine(a[1],"Commons.dll"))){var update=All(commons.MainModule.Types).Single(t=>t.FullName=="Commons.AudioSystem").Methods.Single(m=>m.Name=="Update");var items=update.Body.Instructions;int lastVolume=-1,audioHook=-1,hooksCount=0;for(int i=0;i<items.Count;i++){var call=items[i].Operand as MethodReference;if(call==null)continue;if(call.Name=="set_volume")lastVolume=i;if(call.DeclaringType.FullName=="OneWaySpeaker.Hooks" && call.Name=="AudioUpdated"){audioHook=i;hooksCount++;}}if(hooksCount!=1 || audioHook<=lastVolume || lastVolume<0)throw new Exception("Native audio modulation must run once after native volume updates");Console.WriteLine("Native BGM gain hook runs after all original audio volume updates.");}}}



